`_resolveClosurePath` clamping version:

```dart
/// Lexical `./`/`../` resolution of an import reference against the
/// importing file's directory — `WidgetManifest._resolvePath` verbatim:
/// `..` at the widget root CLAMPS in-root (the runtime never fails here;
/// it would read the clamped path and marker it only when the read
/// misses). Returns null when the reference resolves to nothing in-root
/// — the runtime would boot that as a `file not found` marker, so the
/// install refuses it instead.
static String? _resolveClosurePath(String sourceDir, String ref) {
 final segments = '$sourceDir/$ref'.split('/');
 final out = <String>[];
 for (final segment in segments) {
   if (segment == '.' || segment.isEmpty) continue;
   if (segment == '..') {
     if (out.isNotEmpty) out.removeLast(); // clamped at the root
     continue;
   }
   out.add(segment);
 }
 if (out.isEmpty) return null;
 return out.join('/');
}
``

